        for c in range(len(g[0])):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen.add((a,b)); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
