        gr.setdefault(tuple(sorted((r-mr,c-mc) for r,c in cells)),[]).append((col,cells))
    partnered={}
    for k,v in gr.items():
        if len(v)>1:
            for col,cells in v: partnered[(col,min(cells))] = cells
    # changed comp: diff input/output
    gi,go = G[name+' input'], G[name+' output']
    changed=set()
    for r in range(len(gi)):
        for c in range(len(gi[0])):
            if gi[r][c]!=go[r][c]: changed.add((r,c))
